 const t=chosen(),s=D.stats(t,save.levels[t.id]),next=D.stats(t,Math.min(5,s.level+1));$('silver').textContent=save.silver.toLocaleString('ru');$('xp').textContent=save.xp.toLocaleString('ru');$('career').textContent=`${save.battles} боёв · ${save.wins} побед`;$('saveStatus').textContent=Platform.status;
