 $('tankClass').textContent=`${t.cls.toUpperCase()} / ${roman[s.level-1]}`;$('tankName').textContent=t.name;$('tankDesc').textContent=t.description;$('nationLabel').textContent=t.nation.toUpperCase();
 const entries=[['Огневая мощь',s.damage+' ед.',s.damage/300],['Прочность',s.hp+' HP',s.hp/1600],['Скорость',Math.round(s.speed*3.6)+' км/ч',s.speed/20],['Масса',s.mass+' т',s.mass/70],['Двигатель',s.power+' л.с.',s.power/800],['Броня',s.armor+'%',s.armor/40],['Перезарядка',s.reload.toFixed(2)+' с',1-s.reload/7]];
 $('stats').innerHTML=entries.map(([name,value,ratio])=>`<div class="stat"><div><span>${name}</span><b>${value}</b></div><div class="stat-track"><i style="width:${Math.min(100,ratio*100)}%"></i></div></div>`).join('');
