 $('tankCards').innerHTML=D.tanks.filter(v=>v.n===t.n).map(v=>`<button class="tank-card ${v.id===t.id?'selected':''}" data-tank="${v.id}" aria-label="Выбрать танк ${v.name}"><small>${v.cls.toUpperCase()}</small><span class="card-num">0${v.c+1}</span><strong>${v.name}</strong><em>${save.owned[v.id]?roman[save.levels[v.id]-1]+' УРОВЕНЬ':'🔒 '+D.price(v.id).xp+' XP / '+D.price(v.id).silver+' ◉'} ${v.id===t.id?'· ВЫБРАН':''}</em>${tankSVG}</button>`).join('');$('tankCards').querySelectorAll('button').forEach(b=>b.onclick=()=>selectTank(b.dataset.tank));$('mapSelect').value=save.map;updateMapCard();
