function updateMarkers(){for(const [t,el]of markers){if(!t.alive){el.hidden=true;continue;}const friendly=t.team===player.team;el.className='marker '+(friendly?'friendly':'');const dist=player.group.position.distanceTo(t.group.position),visible=friendly||(dist<player.spec.view*(1-t.spec.camo*.25)&&los(player,t));if(visible&&!friendly&&!t.seen&&player.alive){t.seen=true;record.spotted++;}t.visible=visible;const point=t.group.position.clone().add(new V(0,4.1,0)).project(camera);el.hidden=!visible||point.z>1||point.z<0||Math.abs(point.x)>1.15||Math.abs(point.y)>1.15;if(!el.hidden){el.style.left=(point.x*.5+.5)*innerWidth+'px';el.style.top=(-point.y*.5+.5)*innerHeight+'px';el.innerHTML=`${friendly?'◆':'◇'} ${t.spec.name}<div><i style="width:${t.hp/t.spec.hp*100}%"></i></div>${Math.ceil(t.hp)} · ${Math.round(dist)} м`;}}}
