function updateHUD(){updatePenetration();const a=tanks.filter(t=>t.alive&&t.team===0).length,b=tanks.filter(t=>t.alive&&t.team===1).length;$('alliesScore').textContent=a;$('enemiesScore').textContent=b;$('timer').textContent=`${Math.floor(battleTime/60).toString().padStart(2,'0')}:${Math.floor(battleTime%60).toString().padStart(2,'0')}`;$('hpText').textContent=`${Math.ceil(player.hp)} / ${player.spec.hp}`;$('hpBar').style.width=player.hp/player.spec.hp*100+'%';$('speedText').textContent=Math.round(Math.abs(player.speed)*3.6)+' км/ч';$('reloadLabel').textContent=!player.alive?'МАШИНА УНИЧТОЖЕНА':player.reload>.05?`ПЕРЕЗАРЯДКА ${player.reload.toFixed(1)} с`:'ОРУДИЕ ГОТОВО';$('reloadBar').style.width=(1-player.reload/player.spec.reload)*100+'%';$('objectiveText').textContent=Math.abs(capture)>1?`${capture>0?'ВАША КОМАНДА':'ПРОТИВНИК'} · БАЗА A ${Math.floor(Math.abs(capture))}%`:'ЗАХВАТИТЕ БАЗУ A';$('captureBar').style.width=Math.abs(capture)+'%';$('captureBar').style.background=capture>=0?'#80c7c0':'#e78c72';$('range').textContent=player.reload>.05?`${player.reload.toFixed(1)} С`:`${Math.round(player.group.position.distanceTo(lastAimPoint))} М · ББ`;document.querySelector('.reticle').style.transform=`scale(${(aiming?.66:1)+Math.abs(player.speed)*.015+player.reload*.07})`;drawMinimap();if(elapsed>22&&!save.tutorial){save.tutorial=true;persist();$('tutorialHint').textContent='';}}
function drawMinimap(){const ctx=$('minimap').getContext('2d'),size=220,scale=size/arena.size;ctx.fillStyle=arena===D.maps.desert?'#655d47':arena===D.maps.winter?'#56686e':'#394d43';ctx.fillRect(0,0,size,size);ctx.strokeStyle='#ffffff0e';ctx.lineWidth=1;for(let i=0;i<=5;i++){ctx.beginPath();ctx.moveTo(i*44,0);ctx.lineTo(i*44,220);ctx.moveTo(0,i*44);ctx.lineTo(220,i*44);ctx.stroke();}const X=x=>110+x*scale,Z=z=>110-z*scale;ctx.fillStyle='#adbaab50';for(const o of obstacles){ctx.beginPath();ctx.arc(X(o.x),Z(o.z),o.r*scale,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#ddc88b';ctx.beginPath();ctx.arc(110,110,12*scale,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#eddbab';ctx.font='11px sans-serif';ctx.fillText('A',107,114);for(const t of tanks){if(!t.alive||(t.team===1&&!t.visible))continue;ctx.save();ctx.translate(X(t.group.position.x),Z(t.group.position.z));ctx.rotate(t.yaw);ctx.fillStyle=t.isPlayer?'#fff0ba':t.team===0?'#83d0c1':'#ef997a';ctx.beginPath();ctx.moveTo(0,-5);ctx.lineTo(4,4);ctx.lineTo(-4,4);ctx.closePath();ctx.fill();if(t.isPlayer){ctx.strokeStyle='#fff0ba70';ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-11,-24);ctx.moveTo(0,0);ctx.lineTo(11,-24);ctx.stroke();}ctx.restore();}}
