function details(){const s=D.stats(chosen(),save.levels[save.selected]);showModal(`<div class="eyebrow">ПАСПОРТ МАШИНЫ · ${s.nation.toUpperCase()}</div><h2>${s.name}</h2><table>${[['Класс',s.cls],['Уровень',s.level+'/5'],['Прочность',s.hp+' HP'],['Урон',s.damage],['Перезарядка',s.reload+' с'],['Скорость',Math.round(s.speed*3.6)+' км/ч'],['Поворот корпуса',(s.turn*180/Math.PI).toFixed(0)+' °/с'],['Поворот башни',(s.turret*180/Math.PI).toFixed(0)+' °/с'],['Снижение урона бронёй',s.armor+'%'],['Дальность обзора',s.view+' м'],['Оптическое увеличение',s.zoom.toFixed(2)+'×'],['Точность',Math.round((1-s.spread)*1000)/10+'%'],['Разброс',s.spread.toFixed(3)+' рад'],['Время сведения',s.aim.toFixed(2)+' с'],['Прочность ходовой',s.tracks+' (паспорт)'],['Маскировка',Math.round(s.camo*100)+'%']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</table><p class="help-note">Оптика включается удержанием Shift. Увеличение зависит от класса, нации и уровня модернизации.</p><button id="closeDetails" class="secondary">← Назад в ангар</button>`);$('closeDetails').onclick=()=>$('modal').hidden=true;}
function help(){showModal('<div class="eyebrow">КУРС МОЛОДОГО КОМАНДИРА</div><h2>Займите свой рубеж</h2><p>В одиночном режиме вы и два союзных бота сражаетесь против трёх противников. В локальной сети — честный бой 1 × 1.</p><div class="tutorial-keys"><span><kbd>W / S</kbd> вперёд / назад</span><span><kbd>A / D</kbd> поворот корпуса</span><span><kbd>Мышь</kbd> башня и камера</span><span><kbd>ЛКМ</kbd> выстрел</span><span><kbd>Shift</kbd> оптика танка</span><span><kbd>Пробел</kbd> выстрел</span><span><kbd>Tab</kbd> состав команд</span><span><kbd>Esc</kbd> пауза</span></div><p>Удерживайте Shift для оптического прицела. Его увеличение зависит от характеристик выбранной машины и растёт с модернизацией.</p><p>Для боя через Radmin хост запускает PLAY.cmd, создаёт лобби и передаёт другу адрес сервера и пятизначный код.</p><button id="closeHelp" class="primary">ПОНЯТНО →</button>');$('closeHelp').onclick=()=>{$('modal').hidden=true;};}
